def balanced(s):
    stack = []
    in_single_quote = False
    in_double_quote = False
    escape_next = False

    for i, ch in enumerate(s):
        # Handle escape sequences inside quotes
        if escape_next:
            escape_next = False
            continue

        if in_single_quote:
            if ch == '\\':
                escape_next = True
            elif ch == "'":
                in_single_quote = False
            continue

        if in_double_quote:
            if ch == '\\':
                escape_next = True
            elif ch == '"':
                in_double_quote = False
            continue

        # Outside quotes
        if ch == "'":
            in_single_quote = True
        elif ch == '"':
            in_double_quote = True
        elif ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack:
                return False
            opening = stack.pop()
            if (opening == '(' and ch != ')') or \
               (opening == '[' and ch != ']') or \
               (opening == '{' and ch != '}'):
                return False

    # Check if any quotes are still open
    if in_single_quote or in_double_quote:
        return False

    # Check if all brackets are closed
    return len(stack) == 0


